class Solution { struct DSU{vector<int> parent,rank;int components;DSU(int n):parent(n+1),rank(n+1),components(n){iota(parent.begin(),parent.end(),0);}int find(int x){return parent[x]==x?x:parent[x]=find(parent[x]);}bool unite(int a,int b){a=find(a);b=find(b);if(a==b)return false;if(rank[a]<rank[b])swap(a,b);parent[b]=a;if(rank[a]==rank[b])++rank[a];--components;return true;}};public:int maxNumEdgesToRemove(int n,vector<vector<int>>& edges){DSU alice(n),bob(n);int used=0;for(auto& edge:edges)if(edge[0]==3&&alice.unite(edge[1],edge[2])){bob.unite(edge[1],edge[2]);++used;}for(auto& edge:edges)if(edge[0]==1){if(alice.unite(edge[1],edge[2]))++used;}else if(edge[0]==2&&bob.unite(edge[1],edge[2]))++used;return alice.components==1&&bob.components==1?edges.size()-used:-1;} };
